import{_ as n,C as t,o as i,c as s,E as a,a2 as l}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"历史批准、专属前驱与再次询问：批准究竟管哪一次？","description":"","frontmatter":{"title":"历史批准、专属前驱与再次询问：批准究竟管哪一次？","article_type":"comparative-study","edition":"research-center","research_question":"历史审批存在、前驱约束与当前动作检查分别建立什么消费边界，哪些重试语义仍需额外证据？","summary":"对照两组独立作者披露的审批契约与同日内部隔离探针，区分历史存在、前驱约束和逐次检查，保留重试与持久消费的未知边界。","sources":["https://github.com/Kyvvu/manifests/blob/main/README.md","https://github.com/Kyvvu/manifests/blob/main/docs/authoring-guide.md","https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/enforcement.py"],"date":"2026-11-22","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261122-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-22-sig-20261122-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-22-sig-20261122-002.md","filePath":"zh/engineering/2026-11-22-sig-20261122-002.md","lastUpdated":null}'),c={name:"zh/engineering/2026-11-22-sig-20261122-002.md"};function d(p,e,h,b,f,m){const r=t("ArticleCover"),o=t("ArticleTableScroll");return i(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-11-22-sig-20261122-002-cover.png",kicker:"研究成果",title:"历史批准、专属前驱与再次询问：批准究竟管哪一次？",summary:"对照两组独立作者披露的审批契约与同日内部隔离探针，区分历史存在、前驱约束和逐次检查，保留重试与持久消费的未知边界。",version:"2026-11-22",languageHref:"/en/engineering/2026-11-22-sig-20261122-002",languageLabel:"English"}),a(o,{language:"zh"}),e[0]||(e[0]=l('<h1 id="历史批准、专属前驱与再次询问-批准究竟管哪一次" tabindex="-1">历史批准、专属前驱与再次询问：批准究竟管哪一次？ <a class="header-anchor" href="#历史批准、专属前驱与再次询问-批准究竟管哪一次" aria-label="Permalink to &quot;历史批准、专属前驱与再次询问：批准究竟管哪一次？&quot;">​</a></h1><p>同一个动作第二次进入检查，系统又问了一次“是否执行”。这是批准丢失，还是原本就要求每次询问？本轮源码隔离探针观察到了再次询问，却没有执行任何外部操作。判断它之前，必须先查清批准的有效期：它只是历史中存在的一次同意，是供某个后继动作消费的前驱，还是只处理眼前这次调用？平台与安全工程师可以用下面的契约表，选择真正适合该机制的第二次调用测试。</p><p>本文的判断是：**历史存在、前驱消费与当前动作检查规定了不同的批准有效期。重试保证必须说清消费的是哪个发生实例，以及哪类证据支持这一边界。**这是一项机制对照，不是两个系统的安全排名。</p><h2 id="历史里有同意-和同意只供一次使用" tabindex="-1">历史里有同意，和同意只供一次使用 <a class="header-anchor" href="#历史里有同意-和同意只供一次使用" aria-label="Permalink to &quot;历史里有同意，和同意只供一次使用&quot;">​</a></h2><p>Kyvvu（智能体策略参考项目）的公开清单仓库把几种规则分别命名。历史审批规则要求任务历史中存在已完成、结果为通过的审批步骤，也可以限制审批种类。专属前驱规则则被文档描述为：一个前驱供一个目标消费。前者回答“以前有没有”，后者进一步提出“哪一个前驱给哪一个目标用”。它们不能仅因为都出现人工审批，就被合并为一次性批准。<a href="https://github.com/Kyvvu/manifests/blob/main/README.md" target="_blank" rel="noreferrer">仓库规则说明</a></p><p>已读的高风险策略使用人工类别的历史审批规则；源码中的轨迹测试分别列出先有通过审批再调用资源，以及缺少审批时阻断的情形。这些是我们读到的测试工件，本轮没有运行该引擎，也没有执行“同一批准对应第二个目标”的引擎测试。<a href="https://github.com/Kyvvu/manifests/blob/main/manifests/compliance/eu-ai-act-high-risk.yaml" target="_blank" rel="noreferrer">高风险策略</a></p><p>顺序限制也有不同粒度。一项金融策略要求资源写入之前存在审批，且中间不能插入模型步骤；另一项处理外部内容的复合策略要求高影响步骤紧邻审批，并在历史查询中计入尝试。这些条件约束了先后与邻接关系，但披露的条件本身没有展示对具体参数、资源身份和唯一外部效果标识的持久消费绑定。<a href="https://github.com/Kyvvu/manifests/blob/main/manifests/compliance/financial-services-dora-mifid.yaml" target="_blank" rel="noreferrer">金融策略</a>、<a href="https://github.com/Kyvvu/manifests/blob/main/manifests/security/owasp-agentic-default.yaml" target="_blank" rel="noreferrer">外部内容策略</a></p><p>一个明确标为示意的例子是：历史中已有一次批准，随后出现两个资源写入请求。检查历史、检查紧邻关系、把一个前驱分配给一个目标，会提出不同的问题。不能只给第一个请求放行，就声称已经知道第二个请求的结果；还要检查被选择的实际规则和消费实现。</p><h2 id="当前动作被问一次-并没有生成一张耐久凭据" tabindex="-1">当前动作被问一次，并没有生成一张耐久凭据 <a class="header-anchor" href="#当前动作被问一次-并没有生成一张耐久凭据" aria-label="Permalink to &quot;当前动作被问一次，并没有生成一张耐久凭据&quot;">​</a></h2><p>AgentSpec（智能体运行约束研究实现）来自另一组作者。固定版本中的人工检查处理器展示当前动作；肯定回答继续并返回同一动作对象，否定回答返回“跳过”。执行器在实际执行动作前应用规则。这建立的是当前内存动作的同步检查路径。<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/enforcement.py" target="_blank" rel="noreferrer">固定版本的检查实现</a>、<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/src/controlled_agent_excector.py" target="_blank" rel="noreferrer">执行器</a></p><p>本轮已完成的内部实验从固定源码抽取相关类，用替身动作和替身基类执行八项隔离检查。两次调用同一人工检查处理器，共询问两次，均返回继续；否定回答得到跳过，而单独的停止处理器得到停止。非法输入后重问、空输入后重问和输入结束也各有保留记录。八项均符合各自预期，不能理解为八项完整系统安全测试。<a href="/joinwell52/assets/evidence/2026-11-22-sig-20261122-002/approval-probe-results.json">内部实验记录</a></p><p>这里需要区别两个容易混淆的结果。实现中的 <code>SKIP</code>（跳过当前动作）不是 <code>STOP</code>（停止处理）；说明文档中“拒绝会停止”的概括应收窄到实际代码路径。另一方面，肯定回答返回同一对象，也不等于得到一份不可变的批准快照。替身对象返回后修改输入的检查，只显示了这个可变替身的引用关系，没有复现真实部署中的并发修改或攻击。<a href="https://github.com/haoyuwang99/AgentSpec/blob/e6fa3902e2cfb9681f454b355691b771f70543f8/README.md" target="_blank" rel="noreferrer">说明与实现对照</a></p><p>隔离实验未运行完整解释器、框架依赖、模型、工具、外部副作用、并发或重启；也未运行另一项目的引擎。已检查路径中没有展示持久批准标识、消费台账或重启协议。这支持“证据尚未建立持久消费保证”，不支持“整个产品一定没有这种能力”。</p><h2 id="把第二次发生写进契约表" tabindex="-1">把第二次发生写进契约表 <a class="header-anchor" href="#把第二次发生写进契约表" aria-label="Permalink to &quot;把第二次发生写进契约表&quot;">​</a></h2><p>下表是依据已读材料与内部实验形成的研究解释。每行同时写明证据形态和未回答的问题，避免把文档承诺、可见代码和实际执行混为一谈。</p><table tabindex="0"><thead><tr><th>机制与样本</th><th>当前证据支持什么</th><th>应继续追问哪次发生</th></tr></thead><tbody><tr><td>历史审批存在：策略清单</td><td>文档与已读工件要求历史中存在合格审批；本轮未运行引擎</td><td>同一历史批准面对第二个目标时，选中的规则如何裁决？</td></tr><tr><td>顺序或紧邻：金融与外部内容策略</td><td>已读条件限制中间步骤或要求直接邻接；不是持久消费实测</td><td>插入一步、增加一次尝试之后，批准仍满足条件吗？</td></tr><tr><td>专属前驱：规则说明</td><td>文档声明一个前驱供一个目标消费；所读已装载清单未使用此规则</td><td>第二个目标怎样保留或消费前驱？被阻断的尝试算消费吗？</td></tr><tr><td>当前动作检查：固定检查处理器</td><td>可见实现与内部隔离调用显示逐次询问；拒绝跳过当前动作</td><td>同一调用再次进入时是否重新询问？完整执行器重试仍待测</td></tr></tbody></table><p>前三行的来源为上述规则说明与策略文件；第四行为固定源码及内部实验。表格没有一行声称重启后耐重放、并发消费原子性或外部效果恰好一次已经验证。</p><p>这张表给出的行动很具体：先由集成方指出实际选中的规则、适配器与调用入口，再由评审者把批准对象、有效期、消费单位和证据形态补齐，最后选择对应的第二次发生。若配置宣称专属消费，却只能提交“历史里有一次通过”的记录，就应暂停对该消费保证的验收；缺失证据不能由更强措辞补上。对于逐次询问的机制，重复出现问题本身则不构成违约。</p><h2 id="两种容易误判的反例" tabindex="-1">两种容易误判的反例 <a class="header-anchor" href="#两种容易误判的反例" aria-label="Permalink to &quot;两种容易误判的反例&quot;">​</a></h2><p>本地同步交互可能有意每次都询问，根本没有可跨进程复用的批准凭据。在这种使用范围内，再次询问是政策本身，不宜当作批准丢失。相反，专属前驱的文档语义可能已由未公开引擎实现；未取得引擎证据，也不能据此宣布该机制无效。</p><p>还要保留适配器语境。通用引擎文档把最高严重级别作为阻断条件，其他级别通常警告；特定编程适配器清单又把较高级别映射为询问。脱离实际适配器说“这个严重级别总会阻断”，会把条件性规则误写成通用行为。公开清单仓库是私有平台生成的镜像；一次公开合并也不能单独证明部署已交付。<a href="https://github.com/Kyvvu/manifests/blob/main/docs/authoring-guide.md" target="_blank" rel="noreferrer">编写指南</a></p><p>因此，不存在统一的“再调用一次就能测清批准安全”的捷径。历史查询、邻接约束、专属消费和同步询问，需要不同的预期结果。测试前未定义预期，得到再次询问、拒绝或放行，都可能被解释成自己想要的结论。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>两组外部作者的工件各自承担自身契约的一手证据；它们作者独立，但没有互相复现或认证。文中“文档描述”只指公开契约，“已读实现”只指限定的固定源码，“内部实验”只指本地隔离执行，“研究解释”则是基于这些材料作出的比较。引用不等于认可，发表或仓库公开不等于验证，内部运行成功不等于普遍有效。</p><p>材料截止为本轮同日研究对象：策略镜像捕获树为 <code>d7062e2de2b42144219f387106d81e44b1aa204f</code>（策略工件版本指纹），检查实现固定提交为 <code>e6fa3902e2cfb9681f454b355691b771f70543f8</code>（源码版本指纹）。链接中的可变主分支仅供定位，判断依据是已捕获版本。本轮没有在写作阶段更新材料。<a href="/joinwell52/assets/evidence/2026-11-22-sig-20261122-002/approval-probe-results.json">内部实验及版本边界</a></p><p>下一步不是先要求所有机制拥有同一种凭据，而是为选定契约补上缺失的发生实例：专属前驱需要第二目标与被阻断尝试的真实引擎轨迹；逐次检查需要完整执行器中的重试轨迹。涉及跨进程承诺时，再增加重启、并发与实际副作用证据。在这些证据取得之前，哪一次批准能够跨过哪一次重试，仍应留在未验收项中。</p>',26))])}const _=n(c,[["render",d]]);export{u as __pageData,_ as default};
